examples.content:
.interactive { position: relative; z-index: 0; }
.interactive::before, .interactive::after { content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; }
.interactive::before { z-index: 1; }
.interactive__content { position: relative; z-index: 2; }
.interactive::after { z-index: 3; }
.interactive[aria-selected='true']::before { background: var(--color-interaction-active-brand); }
@media (hover: hover) and (pointer: fine) { .interactive:hover:not(:disabled)::after { background: var(--color-interaction-hover); } }
.interactive:active:not(:disabled)::after { background: var(--color-interaction-pressed); }

.text-body-medium {
  font-family: var(--typography-font-family-ui);
  font-size: var(--typography-fontsize-md);
  line-height: var(--typography-lineheight-md);
  font-weight: var(--typography-weight-regular);
  letter-spacing: var(--typography-letterspacing-negative-half);
}
